<?php include 'verifica_login.php'; include 'conexao.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1)die('ID inválido.');mysqli_begin_transaction($conexao);try{$e=mysqli_query($conexao,"SELECT id_edicao FROM edicoes WHERE id_revista=$id");if(!$e)throw new Exception(mysqli_error($conexao));while($ed=mysqli_fetch_assoc($e)){ $eid=(int)$ed['id_edicao'];$arts=mysqli_query($conexao,"SELECT id_artigo FROM artigos WHERE id_edicao=$eid");if(!$arts)throw new Exception(mysqli_error($conexao));while($a=mysqli_fetch_assoc($arts)){ $aid=(int)$a['id_artigo'];if(!mysqli_query($conexao,"DELETE FROM artigo_autor WHERE id_artigo=$aid"))throw new Exception(mysqli_error($conexao)); }if(!mysqli_query($conexao,"DELETE FROM artigos WHERE id_edicao=$eid"))throw new Exception(mysqli_error($conexao));}if(!mysqli_query($conexao,"DELETE FROM edicoes WHERE id_revista=$id"))throw new Exception(mysqli_error($conexao));if(!mysqli_query($conexao,"DELETE FROM revistas WHERE id_revista=$id"))throw new Exception(mysqli_error($conexao));mysqli_commit($conexao);header('Location: lista_revistas.php');exit;}catch(Exception $e){mysqli_rollback($conexao);die('Não foi possível excluir a revista: '.htmlspecialchars($e->getMessage()));}
